{
  "metric": "avg_total_amount",
  "target_window": "2025-01-20",
  "baseline_window": "2025-01-06, 2025-01-13, 2025-01-27",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "Average total amount per yellow taxi trip on Monday 2025-01-20 was higher than the average of the other three Mondays in January 2025 (2025-01-06, 2025-01-13, 2025-01-27).",
      "support_if": "avg_total_amount on 2025-01-20 > mean(avg_total_amount on 2025-01-06, 2025-01-13, 2025-01-27) by a meaningful margin (e.g., >5%).",
      "refute_if": "avg_total_amount on 2025-01-20 is within normal variance of the other three Mondays (e.g., <5% difference)."
    },
    {
      "id": "H1",
      "kind": "holiday",
      "statement": "Monday 2025-01-20 was Martin Luther King Jr. Day (federal holiday), which altered the passenger mix (e.g., more tourists, fewer commuters) and/or triggered holiday surcharges, raising avg_total_amount.",
      "support_if": "us_holidays confirms 2025-01-20 is a federal holiday (is_national=true) and the other three Mondays are not holidays; trip count on 2025-01-20 differs significantly from baseline Mondays.",
      "refute_if": "2025-01-20 is not a holiday, or trip count and fare patterns are similar to baseline Mondays."
    },
    {
      "id": "H2",
      "kind": "weather",
      "statement": "Adverse weather (precipitation, snow, or extreme cold) on 2025-01-20 increased trip distances/durations or triggered congestion surcharges, raising avg_total_amount.",
      "support_if": "nyc_weather_daily shows prcp_mm > 0, snow_mm > 0, or tmin_c < -5°C on 2025-01-20, while baseline Mondays had milder conditions; avg_trip_distance on 2025-01-20 is higher.",
      "refute_if": "Weather on 2025-01-20 was similar to or better than baseline Mondays, and avg_trip_distance did not increase."
    },
    {
      "id": "H3",
      "kind": "fare_mix",
      "statement": "The fare composition on 2025-01-20 shifted toward higher-fare segments (e.g., more airport trips, longer distances, higher tip percentages) compared to baseline Mondays.",
      "support_if": "avg_trip_distance on 2025-01-20 is significantly higher than baseline Mondays, and/or trip count is lower (suggesting fewer short commuter trips).",
      "refute_if": "avg_trip_distance and trip count on 2025-01-20 are in line with baseline Mondays."
    },
    {
      "id": "H4",
      "kind": "zone_mix",
      "statement": "Pickup/drop-off zone mix shifted on 2025-01-20 (e.g., more trips from/to airports or high-fare zones) compared to baseline Mondays, increasing avg_total_amount.",
      "support_if": "If zone-level data were available, we would see higher share of trips from airports (JFK, LGA, EWR) or Manhattan core on 2025-01-20. Since yellow_daily lacks zone detail, we proxy via avg_trip_distance and trip count.",
      "refute_if": "avg_trip_distance and trip count show no meaningful shift."
    },
    {
      "id": "H5",
      "kind": "data_quality",
      "statement": "The spike on 2025-01-20 is an artifact of data quality issues (e.g., missing trips, duplicate records, or fare calculation errors in the daily aggregate).",
      "support_if": "Trip count on 2025-01-20 is anomalously low or high vs. baseline Mondays, or avg_total_amount is an extreme outlier (>3 std dev from January Mondays).",
      "refute_if": "Trip count and avg_total_amount on 2025-01-20 are within expected ranges for a January Monday."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Get avg_total_amount, trips, avg_trip_distance for target Monday 2025-01-20 and baseline Mondays 2025-01-06, 2025-01-13, 2025-01-27 from whybot.yellow_daily.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Check if 2025-01-20 is a federal holiday and confirm the other three Mondays are not holidays using whybot.us_holidays.",
      "tables": ["whybot.us_holidays"]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Get daily weather (prcp_mm, snow_mm, tmax_c, tmin_c) for 2025-01-20 and the three baseline Mondays from whybot.nyc_weather_daily.",
      "tables": ["whybot.nyc_weather_daily"]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Compare avg_trip_distance and trips on 2025-01-20 vs. baseline Mondays to infer fare mix shifts (already covered by H0 query; no additional table needed).",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H5",
      "purpose": "Assess data quality by checking if trip count and avg_total_amount on 2025-01-20 are outliers vs. all January 2025 Mondays (4 days) using whybot.yellow_daily.",
      "tables": ["whybot.yellow_daily"]
    }
  ],
  "rationale": "The plan quantifies the metric jump (H0) and tests four competing explanations: holiday effect (H1, MLK Day), weather (H2), fare/zone mix via distance and volume proxies (H3, H4), and data quality (H5). All queries use only catalog tables within the valid date range. The H0 and H3/H5 queries share the same yellow_daily pull; H1 and H2 are independent lookups. No zone-level query is possible with current catalog (yellow_daily lacks zone detail), so H4 is evaluated via proxies."
}

